```cpp
#include <bits/stdc++.h>
using namespace std;
#define int long long
#define N 200000
int t1[N];
int lowbit(int x) {
	return ((-x)&x);
}
void add(int x, int y) {
	for (int i = x; i < N; i += lowbit(i)) {
		t1[i] += y;
	}
}
int query(int r) {//f(j,n,aj)<=r
	int res = 0;
	for (int i = r; i; i -= lowbit(i)) {
		res += t1[i];
	}
	return res;
}
int a[N];
int suf[N];
signed main() {
	ios::sync_with_stdio(0);
	cin.tie(0);
	vector<char>c(27);
	int n;
	cin >> n;
	for (int i = 1; i <= n; i++) {
		cin >> a[i];
	}
	map<int, int>mp;
	for (int i = n; i >= 1; i--) {
		mp[a[i]] += 1;
		suf[i] = mp[a[i]];
		add(suf[i], 1);
	}
	mp.clear();
	long long ans = 0;
	for (int i = 1; i <= n; i++) {
		mp[a[i]] += 1;//f(1,i,ai)
		add(suf[i], - 1);
		ans += query(mp[a[i]] - 1);
	}
	cout << ans << '\n';
}
```

